import{z as A,x as i,o as t,c as d,q as r,j as s,D as l,d as e,s as B,S as n,b as a}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"best-of-n 的服务化","description":"","frontmatter":{"title":"best-of-n 的服务化","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/dec-bestofn-serving.md","filePath":"llm/dec-bestofn-serving.md","lastUpdated":1791413859000}'),p={name:"llm/dec-bestofn-serving.md"};function C(m,E,f,N,c,h){const o=i("Mermaid");return t(),d("div",null,[E[2]||(E[2]=r('<h1 id="best-of-n-的服务化" tabindex="-1">best-of-n 的服务化 <a class="header-anchor" href="#best-of-n-的服务化" aria-label="Permalink to &quot;best-of-n 的服务化&quot;">​</a></h1><div class="epigraph"><p>算法课只说「采 $N$ 条选一条」；服务化的全部麻烦在于，这 $N$ 条要同时住在显存里、挤进批里、再等一个打分器判生死。</p><footer>—— 据 Cobbe et al., 2021 与 Snell et al., 2024 的测试时计算口径，按服务视角整理</footer></div><p><a href="/llm/dec-postprocess-pipeline">上一课</a>把单条输出做成管线。本课把候选从 1 条放大到 \\(N\\) 条。算法与打分器谱系基础课已备齐：<a href="/llm/best-of-n">Best-of-N</a> 写了 \\(s(x,y)\\) 的来源与 \\((1-p)^N\\) 的账，<a href="/llm/self-consistency">self-consistency</a> 写了多数票特例，<a href="/llm/prm-guided-search">过程奖励引导搜索</a>写了逐步打分。本课只写服务化：\\(N\\) 条并发的显存与批位、打分器的调度、交付模式的选择。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(N\\) 条独立样本的账在服务上分两段。生成段：\\(N\\) 条共享同一提示前缀，<a href="/llm/kv-prefix-cache">前缀缓存</a>只省一次 prefill，分叉后 KV 与吞吐按 \\(N\\) 涨，\\(N\\) 条在<a href="/llm/sch-continuous-batching-deep">连续批</a>里占 \\(N\\) 个成员位——批里的其他请求跟着变慢。打分段：规则核对要沙箱执行，ORM / PRM 要一次推理服务，沙箱与 RM 都是第二段排队。<span class="marginnote">术语翻译：ORM（结果奖励模型）只看最终答案好不好，像只批「最后一句结论」的老师；PRM（过程奖励模型）对每个推理步骤打分，像逐段批改。PRM 信号更细但每次验收要多看好几眼，这正是「打分段是第二段排队」的由来。</span>串行化（先生成一条、不合格再抽）把占用降下来，却把尾延迟乘上去。缺口是交付模式的选择：什么流量并发、什么流量瀑布、什么流量流式先交。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>三种交付形态</strong>：</p><ol><li><strong>并发同批</strong>：\\(N\\) 条一次提交，前缀共享，全批完成后打分取优。延迟最短，集群占用峰值最高。适合离线判题、竞赛、允许等待的思考模式。</li><li><strong>串行瀑布</strong>：逐条生成逐条验收，合格即停。期望占用低（常常第一条就过），尾延迟方差大（前 \\(N-1\\) 条全败时最痛）。适合验收便宜且通过率不低的流量。</li><li><strong>流式 leader-follow</strong>：先生成的 leader 流式交付，验收窗口内打分；不过关再切换或补抽。体验最好，协议最复杂——切换前用户看到的与最终交付可能不同，要写进帧协议。</li></ol><p><strong>打分器并行化</strong>：\\(N\\) 条打分一次批量提交（RM 的批处理吞吐远高于逐条）；执行沙箱池化，超时计入验收。打分与下一段生成重叠，别串在关键路径上。</p>',9)),(t(),s(n,null,{default:l(()=>[B(o,{id:"mermaid-39",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E6%8F%90%E7%A4%BA%20x%22%5D%20--%3E%20SH%5B%22%E5%89%8D%E7%BC%80%E5%85%B1%E4%BA%AB%E4%B8%80%E6%AC%A1%20prefill%22%5D%0A%20%20SH%20--%3E%20GEN%5B%22N%20%E6%9D%A1%E5%80%99%E9%80%89%E5%88%86%E5%8F%89%E8%A7%A3%E7%A0%81%22%5D%0A%20%20GEN%20--%3E%20MODE%7B%22%E4%BA%A4%E4%BB%98%E5%BD%A2%E6%80%81%22%7D%0A%20%20MODE%20--%3E%7C%E5%B9%B6%E5%8F%91%7C%20ALL%5B%22%E5%85%A8%E6%89%B9%E5%AE%8C%E6%88%90%E5%86%8D%E6%89%93%E5%88%86%22%5D%0A%20%20MODE%20--%3E%7C%E7%80%91%E5%B8%83%7C%20ONE%5B%22%E9%80%90%E6%9D%A1%E7%94%9F%E6%88%90%E9%80%90%E6%9D%A1%E9%AA%8C%E6%94%B6%22%5D%0A%20%20MODE%20--%3E%7C%E6%B5%81%E5%BC%8F%7C%20LEAD%5B%22leader%20%E5%85%88%E4%BA%A4%EF%BC%8C%E9%AA%8C%E6%94%B6%E7%AA%97%E5%8F%A3%E5%86%85%E6%89%93%E5%88%86%22%5D%0A%20%20ALL%20--%3E%20SC%5B%22%E6%89%93%E5%88%86%E5%99%A8%E6%89%B9%E9%87%8F%EF%BC%9ARM%20%2F%20%E6%B2%99%E7%AE%B1%20%2F%20%E5%A4%9A%E6%95%B0%E7%A5%A8%22%5D%0A%20%20ONE%20--%3E%20SC%0A%20%20LEAD%20--%3E%20SC%0A%20%20SC%20--%3E%20PICK%5B%22argmax%20s%EF%BC%8C%E4%BA%A4%E4%BB%98%E4%B8%80%E6%9D%A1%22%5D%0A"})]),fallback:l(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,[e("成本结构沿用"),a("a",{href:"/llm/serving-cost-model"},"服务成本模型"),e("：\\(N\\) 条里只交付一条，用户可见 token 的有效产出除以 \\(N\\)，验收增益要拿 \\(N\\times C_{\\mathrm{tok}}\\) 换。三形态在同一坐标系里各有工作区：通过概率 \\(p\\) 高的流量，瀑布的期望生成条数 \\(1/p\\) 小于 \\(N\\)，平均占用最低；\\(p\\) 低的流量瀑布会滑到 \\(N\\) 条全跑，比并发还贵——形态选择按桶级的 \\(p\\) 估，而 \\(p\\) 恰是 "),a("a",{href:"/llm/best-of-n"},"Best-of-N 课"),e("里难度分桶的量。打分器弱时 \\(N\\) 是黑客放大器，RM 分数曲线与真值曲线要分开报；这条边界在服务上的落点是：验收指标用双曲线，报警挂在真值侧而不是 \\(s\\) 侧。")],-1)),(t(),s(n,null,{default:l(()=>[B(o,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E4%B8%80%E6%89%B9%E6%B5%81%E9%87%8F%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20P%7B%22%E6%A1%B6%E7%BA%A7%E9%80%9A%E8%BF%87%E7%8E%87%20p%20%E6%98%AF%E5%A4%9A%E5%B0%91%EF%BC%9F%22%7D%0A%20%20P%20--%3E%7Cp%20%E9%AB%98%EF%BC%8C%E9%AA%8C%E6%94%B6%E4%BE%BF%E5%AE%9C%7C%20W%5B%22%E4%B8%B2%E8%A1%8C%E7%80%91%E5%B8%83%EF%BC%9A%E6%9C%9F%E6%9C%9B%E5%8F%AA%E7%94%9F%E6%88%90%201%2Fp%20%E6%9D%A1%22%5D%0A%20%20P%20--%3E%7Cp%20%E4%BD%8E%7C%20C%5B%22%E5%B9%B6%E5%8F%91%E5%90%8C%E6%89%B9%EF%BC%9AN%20%E6%9D%A1%E4%B8%80%E6%AC%A1%E8%B7%91%E5%AE%8C%22%5D%0A%20%20P%20--%3E%7C%E4%BA%A4%E4%BA%92%E6%B5%81%E9%87%8F%EF%BC%8C%E4%BD%93%E9%AA%8C%E4%BC%98%E5%85%88%7C%20S%5B%22%E6%B5%81%E5%BC%8F%20leader-follow%22%5D%0A%20%20W%20--%3E%20W2%5B%22%E6%9C%80%E7%97%9B%E6%83%85%E5%BD%A2%EF%BC%9A%E5%89%8D%20N-1%20%E6%9D%A1%E5%85%A8%E8%B4%A5%EF%BC%8C%E5%B0%BE%E5%BB%B6%E8%BF%9F%E5%B0%96%E5%B3%B0%22%5D%0A%20%20C%20--%3E%20C2%5B%22%E5%8D%A0%E7%94%A8%E5%B3%B0%E5%80%BC%E9%AB%98%EF%BC%8C%E4%BD%86%E5%BB%B6%E8%BF%9F%E7%A1%AE%E5%AE%9A%22%5D%0A"})]),fallback:l(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<p><span class="marginnote">用数字感受形态选择：\\(p=0.8\\) 时瀑布平均只生成 \\(1/0.8=1.25\\) 条，比并发 \\(N=8\\) 省得多；\\(p=0.1\\) 时瀑布平均要 10 条，若 \\(N=8\\) 则几乎每次都全跑满还常常全败——比并发更贵、体验更差。所以「瀑布一定省」是错觉，关键看桶级的 \\(p\\)。</span></p><p><span class="marginnote">前缀共享省的是 prefill 不是 decode：64 条候选分叉后的 KV 是 64 份，<a href="/llm/decode-memory-wall">decode 显存墙</a>照撞。先把 \\(N\\) 上限钉在容量公式上，再谈并发形态。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要全局 \\(N\\)：按难度或自洽不确定性调节，是测试时计算的最优策略（<a href="/llm/best-of-n">Best-of-N 课</a>引 Snell 的结论）。<span class="marginnote">常见误区：初学者容易把 \\(N\\) 设成全局常数（比如一律 64）。对一半都能答对的简单流量，这是把算力烧在 32 条多余候选上；把省下的预算挪给难题，同样的总成本能换到更高的整体准确率——这就是「按难度分配测试时算力」。</span>验收便宜、可通过率稳定的流量先试瀑布，别直接上并发。流式切换的产品语义（用户是否可见「正在换答案」）是 UX 决策，但协议层必须能表达。打分器服务自身的 SLO 要单独钉：它慢了，\\(N\\) 条白生成。与投机解码叠加时成员位与 KV 还要再乘，先单请求验证再上批。下一课把所有旋钮放进同一条成本-质量曲线。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>三种交付形态：并发同批、串行瀑布、流式 leader-follow；按桶级通过率 \\(p\\) 选形态。</li><li>前缀共享只省 prefill；分叉后 KV 按成员位涨，\\(N\\) 的上限钉在容量上。</li><li>打分器是第二段服务：RM 批打分、沙箱池化、与生成重叠，SLO 单独钉。</li><li>有效产出除以 \\(N\\)；验收增益按 \\(N\\times C_{\\mathrm{tok}}\\) 记账。</li><li>验收看双曲线：真值准确率与打分器分数分开报，报警挂真值侧。</li><li>出处：Cobbe et al., <em>Training Verifiers to Solve Math Word Problems</em>, 2021；Snell et al., <em>Scaling LLM Test-Time Compute Optimally…</em>, 2024；服务账单见 Best-of-N 与服务成本模型课。</li></ul>',6))])}const b=A(p,[["render",C]]);export{F as __pageData,b as default};
